window.__code__["code-w03-react-handcraft-py"] = {"code_id": "code-w03-react-handcraft-py", "kind": "local", "title": "react_handcraft.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w03/react_handcraft.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w03/react_handcraft.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W03 作业1:不依赖任何框架,手写 50 行 ReAct 循环(Function Calling 版)</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 核心:模型只决策不执行,你执行工具→回填 tool 消息→循环直到模型直接答</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 前置: export DASHSCOPE_API_KEY=\u00004\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w03/react_handcraft.py</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\"># 预期:</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\">#   问题1(杭州天气) -&gt; 直接答</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-com\">#   问题2(杭州温度*3) -&gt; 看到 [iter0] 执行 get_weather / [iter1] 执行 calc,然后给答案</span></span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-kw\">import</span> json</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\"><span class=\"c-kw\">from</span> openai <span class=\"c-kw\">import</span> OpenAI  <span class=\"c-com\"># uv pip install openai</span></span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\"><span class=\"c-com\"># DashScope OpenAI 兼容入口</span></span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">client = OpenAI(</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">    api_key=os.environ[<span class=\"c-str\">&quot;DASHSCOPE_API_KEY&quot;</span>],</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">    base_url=<span class=\"c-str\">&quot;https://dashscope.aliyuncs.com/compatible-mode/v1&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\"><span class=\"c-com\"># 1. 工具实现(你的真函数;这里 mock,真实场景接天气/计算 API)</span></span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\"><span class=\"c-kw\">def</span> get_weather(city: str) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    db = {<span class=\"c-str\">&quot;杭州&quot;</span>: <span class=\"c-str\">&quot;28度晴&quot;</span>, <span class=\"c-str\">&quot;北京&quot;</span>: <span class=\"c-str\">&quot;30度多云&quot;</span>}</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> db.get(city, <span class=\"c-str\">&quot;未知&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\"><span class=\"c-kw\">def</span> calc(expression: str) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;安全计算:只允许数字和运算符,禁用内置函数。&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> str(eval(expression, {<span class=\"c-str\">&quot;__builtins__&quot;</span>: {}}, {}))</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">    <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> f<span class=\"c-str\">&quot;计算错误: {e}&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\"><span class=\"c-com\"># 2. 工具说明书(JSON Schema,喂给模型;对照下方\u000026\u0000就是 FunctionTool 自动生成的)</span></span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">TOOLS = [</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    {</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">        <span class=\"c-str\">&quot;type&quot;</span>: <span class=\"c-str\">&quot;function&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">        <span class=\"c-str\">&quot;function&quot;</span>: {</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">            <span class=\"c-str\">&quot;name&quot;</span>: <span class=\"c-str\">&quot;get_weather&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">            <span class=\"c-str\">&quot;description&quot;</span>: <span class=\"c-str\">&quot;查询某城市天气&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">            <span class=\"c-str\">&quot;parameters&quot;</span>: {</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">                <span class=\"c-str\">&quot;type&quot;</span>: <span class=\"c-str\">&quot;object&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">                <span class=\"c-str\">&quot;properties&quot;</span>: {<span class=\"c-str\">&quot;city&quot;</span>: {<span class=\"c-str\">&quot;type&quot;</span>: <span class=\"c-str\">&quot;string&quot;</span>}},</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">                <span class=\"c-str\">&quot;required&quot;</span>: [<span class=\"c-str\">&quot;city&quot;</span>],</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">            },</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">        },</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">    },</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">    {</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">        <span class=\"c-str\">&quot;type&quot;</span>: <span class=\"c-str\">&quot;function&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">        <span class=\"c-str\">&quot;function&quot;</span>: {</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">            <span class=\"c-str\">&quot;name&quot;</span>: <span class=\"c-str\">&quot;calc&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">            <span class=\"c-str\">&quot;description&quot;</span>: <span class=\"c-str\">&quot;计算数学表达式,如 &#x27;28*3&#x27;&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">            <span class=\"c-str\">&quot;parameters&quot;</span>: {</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">                <span class=\"c-str\">&quot;type&quot;</span>: <span class=\"c-str\">&quot;object&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">                <span class=\"c-str\">&quot;properties&quot;</span>: {<span class=\"c-str\">&quot;expression&quot;</span>: {<span class=\"c-str\">&quot;type&quot;</span>: <span class=\"c-str\">&quot;string&quot;</span>}},</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">                <span class=\"c-str\">&quot;required&quot;</span>: [<span class=\"c-str\">&quot;expression&quot;</span>],</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">            },</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">        },</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">    },</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">]</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">NAME2FN = {<span class=\"c-str\">&quot;get_weather&quot;</span>: get_weather, <span class=\"c-str\">&quot;calc&quot;</span>: calc}</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\"><span class=\"c-kw\">def</span> react(user_query: str, max_iters: int = 8) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">    messages = [</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">        {<span class=\"c-str\">&quot;role&quot;</span>: <span class=\"c-str\">&quot;system&quot;</span>, <span class=\"c-str\">&quot;content&quot;</span>: <span class=\"c-str\">&quot;你是助手,能用工具。能直接答就直接答。&quot;</span>},</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">        {<span class=\"c-str\">&quot;role&quot;</span>: <span class=\"c-str\">&quot;user&quot;</span>, <span class=\"c-str\">&quot;content&quot;</span>: user_query},</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">    ]</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">    <span class=\"c-kw\">for</span> i <span class=\"c-kw\">in</span> range(max_iters):</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">        resp = client.chat.completions.create(</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">            model=<span class=\"c-str\">&quot;qwen-plus&quot;</span>, messages=messages, tools=TOOLS</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">        msg = resp.choices[0].message</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">        messages.append(msg.model_dump(exclude_none=<span class=\"c-kw\">True</span>))</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">        <span class=\"c-com\"># 模型没有要调工具 -&gt; 它在给最终答案,结束循环</span></span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> msg.tool_calls:</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> msg.content <span class=\"c-kw\">or</span> <span class=\"c-str\">&quot;(空回复)&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">        <span class=\"c-com\"># 执行每个工具调用,把结果以 tool 角色消息回填</span></span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> call <span class=\"c-kw\">in</span> msg.tool_calls:</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">            name = call.function.name</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">            args = json.loads(call.function.arguments)</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">            print(f<span class=\"c-str\">&quot;  [iter {i}] 执行 {name}({args})&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">            result = NAME2FN[name](**args)</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">            messages.append({</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">                <span class=\"c-str\">&quot;role&quot;</span>: <span class=\"c-str\">&quot;tool&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">                <span class=\"c-str\">&quot;tool_call_id&quot;</span>: call.id,</span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">                <span class=\"c-str\">&quot;content&quot;</span>: str(result),</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">            })</span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">    <span class=\"c-kw\">return</span> <span class=\"c-str\">&quot;(达到最大迭代数,强制停止 — 这就是 W10 doom_loop gate 要治的病)&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">    print(<span class=\"c-str\">&quot;--- 问题1:杭州天气 ---&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">    print(react(<span class=\"c-str\">&quot;杭州天气怎么样?&quot;</span>))</span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">    print(<span class=\"c-str\">&quot;\\n--- 问题2:需调两个工具,杭州温度乘以3 ---&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">    print(react(<span class=\"c-str\">&quot;杭州天气温度乘以3是多少?&quot;</span>))</span></div>\n</div>", "lines": 102, "explanation": "react_handcraft.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W03-手写ReAct与Plan-Execute循环"]};
